#!/usr/bin/env python3 # -- coding: utf-8 -- """ Map-Matching (Strict) — 1Hz GPS 정제 + 후보탐색 + 거리/속도/방향 제약 + Viterbi + WKT 기반 경로 생성/시각화 입력: --gps : 원본 GPS CSV (예: 충남70자1474.csv; PosX/PosY 또는 Latitude/Longitude 포함) --nodes : 도로 노드 CSV (예: mm_nodes_from_routes.csv; id/lat/lon 등 유연 인식) --edges : 도로 엣지 CSV (예: mm_edges_from_routes.csv; from/to/geometry(WKT) 등 유연 인식) --out : 출력 파일 접두어(옵션, 기본: 'matched') 출력: <out>_gps_cleaned.csv — 정제된 GPS (속도/헤딩 기반 스파이크 제거, Hampel 유사 필터) <out>_strict_raw.csv — Viterbi 단계별 최종 후보(딕셔너리)를 CSV로 직렬화 <out>_path_nodes.csv — 최종 경로 노드 시퀀스(중복 제거 후, 최단경로 확장 포함) <out>_route.geojson — 엣지 WKT를 이어 붙인 실제 도로 경로 <out>_map_only.html — 매칭 경로만 시각화 (Folium) 필요 패키지: pip install pandas numpy networkx geopy scikit-learn shapely folium 작성자 메모: - PosX/PosY는 1e6 스케일 감지 후 경위도로 변환 - Transition 제약 (현실성 강화): * 거리 비율 차단: rd/gd > 3 & (rd-gd) > 30m → 전이 불가 * 정지 근처 점프: gd ≤ 5m & rd > 40m → 전이 불가 * 속도 일치성: rd/dt > 45 m/s 또는 (obs_s 낮은데 road_s 과도(≥2.5배, 최소 25m/s)) → 전이 불가 * 헤딩: Δ≥150° 하드블록, 90°~150° 급감, <90° 완만 감점 """ import argparse import json import math from pathlib import Path import folium import networkx as nx import numpy as np import pandas as pd from geopy.distance import geodesic from shapely import wkt from shapely.geometry import LineString, mapping from sklearn.neighbors import BallTree # ----------------------------- 유틸 ----------------------------- def read_csv_any(path: Path): for enc in ("utf-8-sig", "cp949", "euc-kr"): try: return pd.read_csv(path, encoding=enc) except Exception: continue raise RuntimeError(f"CSV 읽기 실패: {path}") def need_scale(series: pd.Series) -> bool: v = pd.to_numeric(series.dropna().astype(str).str.replace(",", "", regex=False), errors="coerce") if v.empty: return False return v.median() > 1000 # 127.xxxxx 같은 정수 스케일 (1e6) 감지 def haversine_m(a, b) -> float: return geodesic(a, b).meters def bearing_deg(p1, p2) -> float: lat1, lon1 = np.radians(p1[0]), np.radians(p1[1]) lat2, lon2 = np.radians(p2[0]), np.radians(p2[1]) dlon = lon2 - lon1 y = np.sin(dlon) * np.cos(lat2) x = np.cos(lat1) * np.cos(lat2) - np.sin(lat1) * np.sin(lat2) * np.cos(dlon) brng = np.degrees(np.arctan2(y, x)) return (brng + 360) % 360 def angle_diff(a, b) -> float: # [-180, 180] 범위의 차 return (a - b + 180) % 360 - 180 # ----------------------- 1) GPS 로드 & 정제 ----------------------- def load_and_clean_gps(gps_path: Path) -> pd.DataFrame: gps_raw = read_csv_any(gps_path).copy() # 컬럼 탐지 if "PosX" in gps_raw.columns and "PosY" in gps_raw.columns: gps_raw["_lon"] = pd.to_numeric(gps_raw["PosX"], errors="coerce") gps_raw["_lat"] = pd.to_numeric(gps_raw["PosY"], errors="coerce") else: lon_c = next((c for c in gps_raw.columns if c.lower() in ["longitude", "lon", "x", "경도"]), None) lat_c = next((c for c in gps_raw.columns if c.lower() in ["latitude", "lat", "y", "위도"]), None) if lon_c is None or lat_c is None: raise RuntimeError("GPS 컬럼을 찾을 수 없음 (PosX/PosY 또는 Latitude/Longitude)") gps_raw["_lon"] = pd.to_numeric(gps_raw[lon_c], errors="coerce") gps_raw["_lat"] = pd.to_numeric(gps_raw[lat_c], errors="coerce") # 스케일 자동 판단 scale = 1e6 if (need_scale(gps_raw["_lon"]) or need_scale(gps_raw["_lat"])) else 1.0 gps_raw["Longitude"] = gps_raw["_lon"] / scale gps_raw["Latitude"] = gps_raw["_lat"] / scale # 타임스탬프 파싱 (있으면) ts_col = next((c for c in ["Timestamp", "정보 발생 일시", "time", "datetime"] if c in gps_raw.columns), None) if ts_col: t = pd.to_datetime(gps_raw[ts_col].astype(str), errors="coerce", format="%Y%m%d%H%M%S") if t.isna().all(): t = pd.to_datetime(gps_raw[ts_col].astype(str), errors="coerce", format="%y%m%d%H%M%S") gps_raw["_t"] = t if gps_raw["_t"].notna().any(): gps_raw = gps_raw.sort_values("_t").reset_index(drop=True) else: gps_raw["_t"] = pd.NaT # 한국 bbox 필터 gps = gps_raw[gps_raw["Latitude"].between(32, 39) & gps_raw["Longitude"].between(124, 132)].reset_index(drop=True) # 1Hz 가정 or dt 계산 d_m, dt_s, head = [0.0], [1.0], [np.nan] for i in range(1, len(gps)): a = (gps.loc[i - 1, "Latitude"], gps.loc[i - 1, "Longitude"]) b = (gps.loc[i, "Latitude"], gps.loc[i, "Longitude"]) d_m.append(haversine_m(a, b)) head.append(bearing_deg(a, b)) if gps["_t"].notna().all(): dt = (gps.loc[i, "_t"] - gps.loc[i - 1, "_t"]).total_seconds() dt_s.append(dt if (dt and dt > 0) else 1.0) else: dt_s.append(1.0) gps["_dist"], gps["_dt"], gps["_speed_mps"], gps["_heading"] = d_m, dt_s, (np.array(d_m) / np.array(dt_s)), head # 스파이크 제거 speed_thresh = 40.0 # m/s ≈ 144 km/h mask_speed = gps["_speed_mps"] <= speed_thresh # 헤딩 점프(이동 <3m & Δheading>120°) 제거 mh = [True] for i in range(1, len(gps)): if gps.loc[i, "_dist"] < 3.0: prev_h, cur_h = gps.loc[i - 1, "_heading"], gps.loc[i, "_heading"] if not np.isnan(prev_h) and not np.isnan(cur_h): if abs(angle_diff(cur_h, prev_h)) > 120: mh.append(False) continue mh.append(True) mask_heading = pd.Series(mh, index=gps.index) # Hampel 유사(rolling median + 4*MAD) s = gps["_speed_mps"].copy() med = s.rolling(9, center=True, min_periods=1).median() mad = (s - med).abs().rolling(9, center=True, min_periods=1).median() + 1e-6 mask_hampel = (s - med).abs() <= 4 * mad clean = gps[mask_speed & mask_heading & mask_hampel].reset_index(drop=True) # 정제 후 헤딩 재계산 d2, h2, dt2 = [0.0], [np.nan], [1.0] for i in range(1, len(clean)): a = (clean.loc[i - 1, "Latitude"], clean.loc[i - 1, "Longitude"]) b = (clean.loc[i, "Latitude"], clean.loc[i, "Longitude"]) d2.append(haversine_m(a, b)) h2.append(bearing_deg(a, b)) if clean["_t"].notna().all(): dt = (clean.loc[i, "_t"] - clean.loc[i - 1, "_t"]).total_seconds() dt2.append(dt if (dt and dt > 0) else 1.0) else: dt2.append(1.0) clean["_dist"], clean["_dt"], clean["_heading"] = d2, dt2, h2 return clean # -------------------- 2) 도로망 로드 & 그래프 -------------------- def normalize_nodes(nodes: pd.DataFrame) -> pd.DataFrame: nid_col = next((c for c in nodes.columns if c.lower() in ["node_id", "id", "idx", "node"]), None) or "Node_ID" if nid_col not in nodes.columns and "Node_ID" in nodes.columns: nid_col = "Node_ID" nlat_col = next((c for c in nodes.columns if c.lower() in ["lat", "latitude", "y"]), None) or "Latitude" nlon_col = next((c for c in nodes.columns if c.lower() in ["lon", "longitude", "x", "lng"]), None) or "Longitude" out = nodes.rename(columns={nid_col: "Node_ID", nlat_col: "Latitude", nlon_col: "Longitude"})[ ["Node_ID", "Latitude", "Longitude"] ].copy() out["Node_ID"] = out["Node_ID"].astype(int) out["Latitude"] = pd.to_numeric(out["Latitude"], errors="coerce") out["Longitude"] = pd.to_numeric(out["Longitude"], errors="coerce") return out def build_graph(nodes_df: pd.DataFrame, edges_df: pd.DataFrame): G = nx.DiGraph() for _, r in nodes_df.iterrows(): G.add_node(int(r["Node_ID"]), lat=float(r["Latitude"]), lon=float(r["Longitude"])) from_col = next((c for c in edges_df.columns if c.lower() in ["from", "u", "src", "source"]), None) to_col = next((c for c in edges_df.columns if c.lower() in ["to", "v", "dst", "target"]), None) geom_col = next((c for c in edges_df.columns if c.lower() in ["geometry", "wkt", "geom"]), None) if not from_col or not to_col: raise RuntimeError("엣지 CSV에 from/to(u/v) 컬럼이 필요합니다.") # 길이 계산 & 지오메트리 보관 def edge_len(row): if geom_col and isinstance(row[geom_col], str): try: line = wkt.loads(row[geom_col]) cs = list(line.coords) if len(cs) < 2: return 1.0 total = 0.0 for i in range(len(cs) - 1): lon1, lat1 = cs[i] lon2, lat2 = cs[i + 1] total += geodesic((lat1, lon1), (lat2, lon2)).meters return total except Exception: pass # fallback: 노드 좌표 직선 길이 u, v = int(row[from_col]), int(row[to_col]) if u in G.nodes and v in G.nodes: a = (G.nodes[u]["lat"], G.nodes[u]["lon"]) b = (G.nodes[v]["lat"], G.nodes[v]["lon"]) return geodesic(a, b).meters return 1.0 edges_df = edges_df.copy() edges_df["_len"] = edges_df.apply(edge_len, axis=1) edge_geom = {} if geom_col and geom_col in edges_df.columns: for _, r in edges_df.iterrows(): u = int(r[from_col]) v = int(r[to_col]) if isinstance(r[geom_col], str): try: edge_geom[(u, v)] = wkt.loads(r[geom_col]) except Exception: pass for _, r in edges_df.iterrows(): u = int(r[from_col]) v = int(r[to_col]) w = float(r["_len"]) G.add_edge(u, v, weight=w) G.add_edge(v, u, weight=w) # 양방향 return G, edge_geom # ---------------- 3) 후보탐색 (커브 구간 반영) ---------------- def is_curve_point(prev, curr, nxt, threshold=30): a1 = bearing_deg(prev, curr) a2 = bearing_deg(curr, nxt) diff = (a2 - a1 + 180) % 360 - 180 return abs(diff) > threshold def build_balltree(nodes_df: pd.DataFrame) -> BallTree: return BallTree(np.radians(nodes_df[["Latitude", "Longitude"]].values), metric="haversine") def get_candidates(i, gps_df, nodes_df, tree, base_radius=10, curve_radius=15, base_k=4, curve_k=6): lat, lon = gps_df.iloc[i][["Latitude", "Longitude"]] prev_pt = gps_df.iloc[i - 1][["Latitude", "Longitude"]].values if i > 0 else None next_pt = gps_df.iloc[i + 1][["Latitude", "Longitude"]].values if i < len(gps_df) - 1 else None curved = False if prev_pt is not None and next_pt is not None: curved = is_curve_point(prev_pt, [lat, lon], next_pt) radius = curve_radius if curved else base_radius max_k = curve_k if curved else base_k q = np.radians([[lat, lon]]) inds = tree.query_radius(q, r=radius / 6371000.0, return_distance=True) idxs = inds[0][0] if len(inds[0]) > 0 else np.array([]) dists = inds[1][0] * 6371000.0 if len(inds[0]) > 0 else np.array([]) if len(idxs) == 0: d, idx = tree.query(q, k=min(max_k, len(nodes_df))) dists = d[0] * 6371000.0 idxs = idx[0] pairs = sorted(zip(dists, idxs), key=lambda x: x[0])[:max_k] return [ { "Node_ID": int(nodes_df.iloc[int(idx)]["Node_ID"]), "Latitude": float(nodes_df.iloc[int(idx)]["Latitude"]), "Longitude": float(nodes_df.iloc[int(idx)]["Longitude"]), "Distance": float(dist), } for dist, idx in pairs ] # --------------- 4) Emission / Transition (Strict) --------------- def emit_prob(distance_m: float, sigma=40.0) -> float: return math.exp(-distance_m / sigma) def edge_heading(G: nx.DiGraph, u: int, v: int) -> float: a = (G.nodes[u]["lat"], G.nodes[u]["lon"]) b = (G.nodes[v]["lat"], G.nodes[v]["lon"]) return bearing_deg(a, b) def trans_prob_strict(G: nx.DiGraph, n1: dict, n2: dict, g1: tuple, g2: tuple, dt: float, obs_heading: float) -> float: if not G.has_node(n1["Node_ID"]) or not G.has_node(n2["Node_ID"]): return 1e-12 if not nx.has_path(G, n1["Node_ID"], n2["Node_ID"]): return 1e-12 try: rd = nx.shortest_path_length(G, n1["Node_ID"], n2["Node_ID"], weight="weight") except Exception: return 1e-12 gd = geodesic(g1, g2).meters # (1) 거리 비율 차단 if gd > 5.0: if (rd / gd) > 3.0 and (rd - gd) > 30.0: return 1e-12 else: if rd > 40.0: return 1e-12 # (2) 속도 일치성 if dt and dt > 0: road_speed = rd / dt obs_speed = gd / dt if road_speed > 45.0: return 1e-12 if obs_speed < 15.0 and road_speed > max(25.0, 2.5 * max(obs_speed, 1.0)): return 1e-12 # (3) 헤딩 페널티 head_term = 1.0 try: road_head = edge_heading(G, n1["Node_ID"], n2["Node_ID"]) except Exception: road_head = np.nan if not np.isnan(obs_heading) and not np.isnan(road_head): diff = abs(angle_diff(road_head, obs_heading)) if diff >= 150: return 1e-12 # U턴 금지 elif diff >= 90: head_term = math.exp(-((diff - 90) / 12.0)) * 0.2 else: head_term = math.exp(-(diff / 25.0)) # (4) 거리 일치 감쇠 dist_term = math.exp(-abs(rd - gd) / 40.0) return max(dist_term * head_term, 1e-12) # --------------------------- 5) Viterbi --------------------------- def run_viterbi_strict(clean_df: pd.DataFrame, nodes_df: pd.DataFrame, G: nx.DiGraph): tree = build_balltree(nodes_df) gps2 = clean_df.copy() gps2["Candidates"] = [get_candidates(i, gps2, nodes_df, tree) for i in range(len(gps2))] viterbi = [] # t=0 first = gps2.iloc[0]["Candidates"] for c in first: c["delta"] = emit_prob(c["Distance"]) c["psi"] = None viterbi.append(first) # t>=1 for t in range(1, len(gps2)): prev = viterbi[t - 1] curr = gps2.iloc[t]["Candidates"] for c in curr: best, bestp = -1.0, None for p in prev: tp = trans_prob_strict( G, p, c, (gps2.iloc[t - 1]["Latitude"], gps2.iloc[t - 1]["Longitude"]), (gps2.iloc[t]["Latitude"], gps2.iloc[t]["Longitude"]), gps2.iloc[t]["_dt"], gps2.iloc[t]["_heading"], ) prob = p["delta"] * tp * emit_prob(c["Distance"]) if prob > best: best, bestp = prob, p c["delta"], c["psi"] = best, bestp viterbi.append(curr) last = max(viterbi[-1], key=lambda x: x["delta"]) path = [last] for t in range(len(gps2) - 1, 0, -1): path.insert(0, path[0]["psi"]) return gps2, path # gps2(정제/후보 포함), 최종 후보 리스트 # --------------- 6) 경로(노드/지오메트리) 생성/시각화 --------------- def build_full_node_path(G: nx.DiGraph, dedup_nodes): full_path = [] for i in range(len(dedup_nodes) - 1): u, v = dedup_nodes[i], dedup_nodes[i + 1] try: sp = nx.shortest_path(G, u, v, weight="weight") if full_path: full_path.extend(sp[1:]) else: full_path.extend(sp) except nx.NetworkXNoPath: if not full_path: full_path.append(u) full_path.append(v) return full_path def stitch_coords_from_edges(G: nx.DiGraph, edge_geom: dict, node_path: list): coords = [] for i in range(len(node_path) - 1): u, v = node_path[i], node_path[i + 1] geom = edge_geom.get((u, v)) or edge_geom.get((v, u)) if geom is not None: seg = [(y, x) for (x, y) in list(geom.coords)] if coords and coords[-1] == seg[0]: coords.extend(seg[1:]) else: coords.extend(seg) else: a = (G.nodes[u]["lat"], G.nodes[u]["lon"]) b = (G.nodes[v]["lat"], G.nodes[v]["lon"]) if not coords or coords[-1] != a: coords.append(a) coords.append(b) return coords def save_outputs(prefix: str, clean_df: pd.DataFrame, path_list: list, G: nx.DiGraph, edge_geom: dict): out_clean = Path(f"{prefix}_gps_cleaned.csv") clean_df.to_csv(out_clean, index=False, encoding="utf-8-sig") # path_list(딕셔너리들)를 직렬화 out_raw = Path(f"{prefix}_strict_raw.csv") pd.DataFrame(path_list).to_csv(out_raw, index=False, encoding="utf-8-sig") # 노드 시퀀스(연속 중복 제거) seq_nodes = [int(p["Node_ID"]) for p in path_list] dedup = [] for n in seq_nodes: if not dedup or dedup[-1] != n: dedup.append(n) # 최단경로 확장 (노드 경로) full_node_path = build_full_node_path(G, dedup) pd.DataFrame({"node_id": full_node_path}).to_csv(f"{prefix}_path_nodes.csv", index=False, encoding="utf-8-sig") # 좌표 라인 (WKT 있으면 이어 붙이기) coords = stitch_coords_from_edges(G, edge_geom, full_node_path) # GeoJSON gj_path = Path(f"{prefix}_route.geojson") if len(coords) >= 2: line = LineString([(lon, lat) for (lat, lon) in coords]) gj = {"type": "FeatureCollection", "features": [{"type": "Feature", "geometry": mapping(line), "properties": {"name": "matched_route"}}]} with open(gj_path, "w", encoding="utf-8") as f: json.dump(gj, f, ensure_ascii=False) else: with open(gj_path, "w", encoding="utf-8") as f: json.dump({"type": "FeatureCollection", "features": []}, f, ensure_ascii=False) # 지도 (매칭 경로만) if len(coords) >= 2: lat_med = np.median([p[0] for p in coords]) lon_med = np.median([p[1] for p in coords]) else: lat_med = clean_df["Latitude"].median() lon_med = clean_df["Longitude"].median() m = folium.Map(location=[lat_med, lon_med], zoom_start=13, control_scale=True) if len(coords) >= 2: folium.PolyLine(coords, weight=5, tooltip="Matched (strict)").add_to(m) m.save(f"{prefix}_map_only.html") return { "gps_cleaned_csv": str(out_clean), "viterbi_raw_csv": str(out_raw), "path_nodes_csv": f"{prefix}_path_nodes.csv", "route_geojson": str(gj_path), "map_only_html": f"{prefix}_map_only.html", } # ------------------------------ MAIN ------------------------------ def main(): ap = argparse.ArgumentParser() ap.add_argument("--gps", required=True, help="원본 GPS CSV") ap.add_argument("--nodes", required=True, help="도로 노드 CSV") ap.add_argument("--edges", required=True, help="도로 엣지 CSV (geometry WKT 권장)") ap.add_argument("--out", default="matched", help="출력 파일 접두어") args = ap.parse_args() gps_path = Path(args.gps) nodes_path = Path(args.nodes) edges_path = Path(args.edges) prefix = args.out # 1) GPS 정제 clean = load_and_clean_gps(gps_path) # 2) 도로망/그래프 nodes_df = normalize_nodes(read_csv_any(nodes_path)) edges_df = read_csv_any(edges_path) G, edge_geom = build_graph(nodes_df, edges_df) # 3) Viterbi (Strict) gps2, path_list = run_viterbi_strict(clean, nodes_df, G) # 4) 저장 paths = save_outputs(prefix, gps2, path_list, G, edge_geom) print("DONE", paths) if name == "main": main()